    for(i=0;i<n;i++) a[i]=(unsigned char)w[i]; a[n]=0;
    for(j=0;j<nrule;j++){
        m=0; k=0;
        while(k<n){
            c=0; while(RR[j][c] && a[k+c]==(unsigned char)RR[j][c]) c++;
            if(RR[j][c]==0){ for(i=0;a[k+i];i++) b[m++]=a[k+i]; k+=i-1; }
            else { b[m++]=a[k]; k++; }
        }
        b[m]=0; n=m; for(i=0;i<=n;i++) a[i]=b[i];
    }
    m=0; k=0;
    while(k<n){
        int cl=0; while(k<n && a[k]!=0) cl++, k++;
        if(cl==1) out[m++]=a[k-cl];
        else { for(j=0;j<nrule;j++) if((int)strlen(RR[j])==cl && !memcmp(RR[j], a+k-cl, cl)) break; out[m++]=256+j; }
    }
    return m;
}
