        for(j=0;p[i]&&p[i]!=' '&&p[i]!='\n';j++) RR[nrule][i+j]=p[i+j];
        RR[nrule][i+j]=0; nrule++;
    }
    fclose(F); free(p);
    int seq[2048]; L=tok(av[3], seq);
    float x[H], sc[2048];
    for(k=0;k<20;k++){
        for(i=0;i<H;i++) x[i]=P[seq[L-1]*H+i]+P[(L-1)*H+i];
        for(n=0;n<N;n++){
            int o=15153408+41030400*n;
            float m=0, v=0, t;
            for(i=0;i<H;i++) m+=x[i]; m/=H;
            for(i=0;i<H;i++) v+=(x[i]-m)*(x[i]-m);
            t=sqrtf(v/H+1e-5);
            for(i=0;i<H;i++) x[i]=(x[i]-m)*P[o+i]/t+P[o+H+i];
            float q[H], vv[H];
            for(i=0;i<H;i++){ q[i]=0; for(j=0;j<H;j++) q[i]+=x[j]*P[o+1536+j*H+i]; }
            for(i=0;i<L;i++){
                float d=0; for(j=0;j<H;j++) d+=q[j]*P[o+3072+j*H+i]; sc[i]=d/27.7128129;
            }
            int mx=0; for(i=1;i<L;i++) if(sc[i]>sc[mx]) mx=i;
            for(i=0;i<L;i++) sc[i]=expf(sc[i]-sc[mx]);
            float tot=0; for(i=0;i<L;i++) tot+=sc[i];
            for(i=0;i<H;i++) vv[i]=0;
            for(i=0;i<L;i++) for(j=0;j<H;j++) vv[j]+=sc[i]/tot*P[o+4608+j*H+i];
            for(i=0;i<H;i++) x[i]+=vv[i];
            m=0; for(i=0;i<H;i++) m+=x[i]; m/=H;
            v=0; for(i=0;i<H;i++) v+=(x[i]-m)*(x[i]-m);
            t=sqrtf(v/H+1e-5);
            for(i=0;i<H;i++) x[i]=(x[i]-m)*P[o+6144+i]/t+P[o+6912+i];
            float gv[C];
            for(i=0;i<C;i++){ float s=P[o+7680+i]; for(j=0;j<H;j++) s+=x[j]*P[o+7680+j*C+i]; gv[i]=s/(1+expf(-s))+P[o+15552+i]; }
            for(i=0;i<H;i++){ float s=P[o+23808+i]; for(j=0;j<C;j++) s+=gv[j]*P[o+23808+j*H+i]; x[i]+=s; }
        }
        int best=0; float bv=0, s;
        for(i=1;i<V;i++){ s=0; for(j=0;j<H;j++) s+=x[j]*P[i*H+j]; if(s>bv){ bv=s; best=i; } }
        for(i=0;RR[best-256]&&RR[best-256][i];i++) putchar(RR[best-256][i]);
        if(best-256<nrule) for(i=0;RR[best-256]&&RR[best-256][i];i++); 
        seq[L++]=best;
    }
    return 0;
}
